import{_ as e,c as t,o as n,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"ADVANCING ARTIFICIAL INTELLIGENCE EDUCATION FOR AMERICAN YOUTH","description":"","frontmatter":{"title":"ADVANCING ARTIFICIAL INTELLIGENCE EDUCATION FOR AMERICAN YOUTH","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/advancing-artificial-intelligence-education-for-american-youth/","publishDate":"2025-04-23T19:02:46-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-23-advancing-artificial-intelligence-education-for-american-youth.md","filePath":"executive-orders/2025-04-23-advancing-artificial-intelligence-education-for-american-youth.md"}'),o={name:"executive-orders/2025-04-23-advancing-artificial-intelligence-education-for-american-youth.md"};function r(l,i,s,c,u,d){return n(),t("div",null,i[0]||(i[0]=[a('<h1 id="advancing-artificial-intelligence-education-for-american-youth" tabindex="-1">ADVANCING ARTIFICIAL INTELLIGENCE EDUCATION FOR AMERICAN YOUTH <a class="header-anchor" href="#advancing-artificial-intelligence-education-for-american-youth" aria-label="Permalink to &quot;ADVANCING ARTIFICIAL INTELLIGENCE EDUCATION FOR AMERICAN YOUTH&quot;">​</a></h1><p>Published: Wednesday, April 23, 2025</p><ul><li><p><strong>Purpose and Vision</strong></p><ul><li>Enhance U.S. leadership in AI technology by equipping youth with necessary skills and knowledge.</li><li>Foster AI competency and early exposure to cultivate curiosity and creativity in future innovators.</li></ul></li><li><p><strong>Key Policies and Actions</strong></p><ul><li>Promote AI literacy among Americans through comprehensive education integration.</li><li>Establish the <strong>White House Task Force on Artificial Intelligence Education</strong> to oversee AI education initiatives. <ul><li>Chaired by the Director of the Office of Science and Technology Policy.</li><li>Comprises various Secretaries and advisors from relevant departments.</li></ul></li></ul></li><li><p><strong>Presidential AI Challenge</strong></p><ul><li>Task Force to develop and implement a Challenge highlighting achievements in AI education within 12 months.</li><li>Aims for wide geographic participation and interdisciplinary exploration among students.</li></ul></li><li><p><strong>K-12 AI Education Initiatives</strong></p><ul><li>Foster public-private partnerships for developing K-12 educational resources.</li><li>Utilize existing federal AI resources to bolster local partnerships for AI education.</li><li>Secretary of Education to issue guidance on grant funds for improving educational outcomes related to AI.</li></ul></li><li><p><strong>Teacher Training Enhancements</strong></p><ul><li>Prioritize AI use in training programs and resources for educators.</li><li>NSF and Secretary of Agriculture to create training opportunities for integrating AI into education.</li></ul></li><li><p><strong>Workforce Development</strong></p><ul><li>Secretary of Labor to increase participation in AI-related Registered Apprenticeships. <ul><li>Collaborate with industry for the development of program standards.</li></ul></li><li>Encourage states to develop AI skills using funding from the Workforce Innovation and Opportunity Act (WIOA).</li></ul></li><li><p><strong>Opportunities for High School Students</strong></p><ul><li>Support high school AI courses and certifications.</li><li>Encourage partnerships with local districts for dual enrollment opportunities in AI programs.</li></ul></li><li><p><strong>Implementation Guidelines</strong></p><ul><li>The order must be executed in accordance with existing laws and available appropriations.</li><li>No new enforceable rights or benefits created through this order.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/advancing-artificial-intelligence-education-for-american-youth/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/advancing-artificial-intelligence-education-for-american-youth/</a></p>',4)]))}const h=e(o,[["render",r]]);export{g as __pageData,h as default};
